dtsPropsFor.GameTabs:
/** Pestañas en orden de lectura. */
  tabs: ReadonlyArray<{ id: string; label: string }>;
  /** id de la pestaña seleccionada. */
  active: string;
  /** Recibe el id elegido con clic o con ←/→, Inicio y Fin. */
  onChange: (id: string) => void;
  /** aria-label del tablist. */
  label: string;
  /** id del tabpanel que controlan. Cada botón recibe el id `${panelId}-tab-${tab.id}`. */
  panelId: string;

dtsPropsFor.HeroSigil:
/** Constrúyelo con `toHeroProfile(hero)`. El color sale de la variable CSS `--hero-accent` de un ancestro (usa `profile.presentation.accent`). */
  profile: {
    id: string;
    name: string;
    type: 'Psico' | 'Energía' | 'Defensa' | 'Control';
    level: number;
    /** Máximo de configuración, no el HP actual de un combate. */
    maxHp: number;
    /** Máximo de configuración, no el MP actual de un combate. */
    maxMp: number;
    /** Golpear, Bloquear, Esquivar, Mental y Velocidad, en ese orden. */
    stats: ReadonlyArray<{ label: string; value: number }>;
    power: {
      name: string;
      level: number;
      status:
        | { kind: 'documented'; description: string; mpCost: number; nominalDamage?: number; implementation: string }
        | { kind: 'uncatalogued'; description: string; implementation: string };
    };
    /** Símbolo y acento provisionales por tipo; nunca hay ilustración asignada. */
    presentation: { symbol: string; accent: string; art: 'absent' };
  };

