dtsPropsFor.CharacterRail:
/** Personajes del rail; `art` es el retrato. */
  characters: Array<{
    id: string;
    name: string;
    /** Subtítulo en mayúsculas bajo el nombre (voz dossier). */
    title: string;
    /** Código de registro, p. ej. `VYR-H2`. */
    code: string;
    /** Etiqueta de archivo, p. ej. `PSICO // ARCHIVO`. */
    archive: string;
    category: string;
    /** Cita del desplegable LORE SIGNAL (oculta hasta que se abre). */
    quote: string;
    /** Entradilla de 1–2 líneas (se recorta a 2). */
    intro: string;
    /** Chips cortos en mayúsculas. */
    tags: string[];
    /** Filas de la pestaña de estadísticas; el valor ya va formateado. */
    stats: Array<{ label: string; value: string }>;
    /** Acento del personaje en hex; debe coincidir con el `accent` de su LabScope. */
    accent: string;
    /** El mismo acento como `r,g,b`. */
    accentRgb: string;
    /** Fondo del escenario en hex. */
    surface: string;
    /** URL de la imagen del retrato y del escenario. */
    art: string;
  }>;
  /** Índice del personaje mostrado (lleva el marcador). */
  selected: number;
  /** Índice pedido (aria-pressed y contador `01 / 03`). Igual que `selected` salvo durante un cambio. */
  requested: number;
  /** true durante la transición de cambio: deshabilita los retratos. */
  busy: boolean;
  /** Movimiento reducido: sin hover ni tap animados. */
  reduced: boolean;
  onSelect: (index: number) => void;

